<script setup lang="ts">
import SoftSelect from '../components/SoftSelect.vue'
import StudentAvatar from '../components/StudentAvatar.vue'
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, post, query, time, isCancelled } from '../lib/api'
import { globalSearch, isAdmin, campusOptions, defaultCampusId } from '../lib/state'
import { openDialog, useResource, label, notify } from '../lib/ui'
import type { ClassRoom, Student } from '../lib/types'
import PageHeader from '../components/PageHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import LoadState from '../components/LoadState.vue'
import StatusBadge from '../components/StatusBadge.vue'
const route = useRoute(); const classId=ref<string | number>(''); const keyword = ref(globalSearch.value); const detail = ref<Student | null>(null)
watch(globalSearch, value => keyword.value = value)
const classes = useResource(() => api<ClassRoom[]>('/classes'))
const {data,loading,error,refresh} = useResource(() => api<Student[]>(`/students${query({classId:classId.value,keyword:keyword.value})}`),[classId,keyword])
const classOptions = computed(() => (classes.data.value || []).map(c => ({value:c.id,label:`${c.name}${c.campusName ? ` · ${c.campusName}` : ''}`})))
watch(data, list => { const id = Number(route.query.studentId); if (id && list?.some(s=>s.id===id)) detail.value = list.find(s=>s.id===id) || null })
async function createStudent() {
  if (await openDialog({title:'新增学生档案',description:'学生创建后将自动建立晚辅课时账户，初始余额为 0。',fields:[{key:'name',label:'学生姓名',required:true},{key:'gender',label:'性别',type:'select',required:true,options:[{value:'男',label:'男'},{value:'女',label:'女'}]},{key:'grade',label:'年级',required:true,placeholder:'例如：三年级'},{key:'classId',label:'所属班级',type:'select',required:true,options:classOptions.value},{key:'parentName',label:'家长姓名',required:true},{key:'parentPhone',label:'家长联系电话',required:true}],submit:v=>post('/students',v),success:'学生档案已建立'})) refresh()
}
async function createClass() { if (await openDialog({title:'创建班级',fields:[{key:'campusId',label:'所属校区',type:'select',required:true,options:campusOptions.value},{key:'name',label:'班级名称',required:true},{key:'teacherName',label:'班主任姓名',required:true}],initial:{campusId:defaultCampusId.value},submit:v=>post('/classes',v),success:'班级创建成功'})) classes.refresh() }
async function showDetail(student: Student) { detail.value = student; try { detail.value = await api<Student>(`/students/${student.id}`) } catch (error) { if (isCancelled(error)) return; notify(`档案详情刷新失败：${(error as Error).message}`, 'error') } }
</script>
<template><PageHeader title="学生档案" subtitle="认识每一个孩子，记录每一段成长。"><button v-if="isAdmin" class="btn secondary" @click="createClass"><AppIcon name="School" :size="16" />创建班级</button><button v-if="isAdmin" class="btn primary" @click="createStudent"><AppIcon name="Plus" :size="17" />新增学生</button></PageHeader><section class="panel"><div class="filter-bar"><div class="search-input"><AppIcon name="Search" :size="17" /><input v-model="keyword" placeholder="搜索学生姓名、家长或手机号" aria-label="搜索学生档案" /></div><SoftSelect v-model="classId" aria-label="筛选班级" :options="[{value:'',label:'全部班级'}, ...(classes.data.value || []).map(c => ({value:c.id,label:c.name + (c.campusName ? ` · ${c.campusName}` : '')}))]" /><span class="filter-count">共 {{ data?.length || 0 }} 位学生</span><button class="icon-btn" aria-label="刷新学生" @click="refresh"><AppIcon name="RefreshCw" :size="17" /></button></div><LoadState :loading="loading" :error="error" :empty="!data?.length" title="还没有学生档案" description="创建班级后，即可添加学生并开始成长记录。" @retry="refresh"><div class="table-wrap"><table><thead><tr><th>学生</th><th>所属校区</th><th>年级 / 班级</th><th>家长联系</th><th>到校状态</th><th>作业完成</th><th>成长积分</th><th>晚辅余额</th><th>操作</th></tr></thead><tbody><tr v-for="(student,index) in data" :key="student.id"><td><div class="person"><StudentAvatar :student="student" /><span><strong>{{ student.name }}</strong><small>{{ label(student.gender) }}</small></span></div></td><td>{{ student.campusName||'—' }}</td><td><strong>{{ student.className }}</strong><small class="block muted">{{ student.grade }}</small></td><td>{{ student.parentName }}<small class="block muted numeric">{{ student.parentPhone }}</small></td><td><StatusBadge :value="student.attendanceStatus" /></td><td class="numeric">{{ student.homeworkCompleted }} / {{ student.homeworkTotal }}</td><td><span class="points-value">{{ student.points }}</span> 分</td><td><span :class="{'text-danger':student.lessonBalance<=3}" class="numeric">{{ student.lessonBalance }}</span></td><td><button class="text-btn" @click="showDetail(student)">查看档案</button></td></tr></tbody></table></div></LoadState></section><Teleport to="body"><div v-if="detail" class="modal-overlay" @mousedown.self="detail=null"><section class="modal detail-modal" role="dialog" aria-modal="true" aria-labelledby="student-title"><header class="modal-header"><div class="person"><StudentAvatar :student="detail" class="large" /><div><span class="eyebrow">学生成长档案 #{{ detail.id }}</span><h2 id="student-title">{{ detail.name }}</h2></div></div><button class="icon-btn" aria-label="关闭档案" @click="detail=null"><AppIcon name="X" /></button></header><div class="detail-body"><div class="detail-grid"><div><span>所属校区</span><strong>{{ detail.campusName||'—' }}</strong></div><div><span>所属班级</span><strong>{{ detail.className }}</strong></div><div><span>年级 / 性别</span><strong>{{ detail.grade }} · {{ label(detail.gender) }}</strong></div><div><span>家长姓名</span><strong>{{ detail.parentName }}</strong></div><div><span>联系电话</span><strong>{{ detail.parentPhone }}</strong></div><div><span>到校状态</span><StatusBadge :value="detail.attendanceStatus" /></div><div><span>签到 / 离校</span><strong>{{ time(detail.checkInTime) }} / {{ time(detail.checkOutTime) }}</strong></div><div><span>成长积分</span><strong>{{ detail.points }} 分</strong></div><div><span>晚辅余额</span><strong>{{ detail.lessonBalance }}</strong></div></div><div class="detail-links"><RouterLink :to="`/family-services?studentId=${detail.id}`" class="btn secondary" @click="detail=null">课程、订餐与头像</RouterLink><RouterLink :to="`/homework?studentId=${detail.id}`" class="btn secondary" @click="detail=null">学习作业<AppIcon name="ArrowUpRight" :size="15" /></RouterLink><RouterLink :to="`/mistakes?studentId=${detail.id}`" class="btn secondary" @click="detail=null">成长错题本<AppIcon name="ArrowUpRight" :size="15" /></RouterLink><RouterLink :to="`/ledger?studentId=${detail.id}`" class="btn secondary" @click="detail=null">课时账本<AppIcon name="ArrowUpRight" :size="15" /></RouterLink></div></div></section></div></Teleport></template>
